class DiagnosticResult(NamedTuple):
    """Container for diagnostic check results.

    Attributes:
        passed (bool): Status of the diagnostic check.
        message (str): Explanatory message or status summary.
        metadata (Dict[str, Any]): Associated telemetry or context metadata.
    """

    passed: bool
    message: str
    metadata: Dict[str, Any]

    @classmethod
    def create(
        cls,
        passed: bool,
        message: str,
        metadata: Optional[Dict[str, Any]] = None,
    ) -> DiagnosticResult:
        """Factory method to construct DiagnosticResult with automatic metadata fallback.

        Args:
            passed: Boolean status indicating check success or failure.
            message: Informative summary of check execution.
            metadata: Optional dictionary containing custom telemetry attributes.

        Returns:
            DiagnosticResult: Fully populated immutable result tuple.
        """
        if metadata is None:
            resolved_metadata = generate_telemetry_metadata()
        else:
            try:
                resolved_metadata = dict(metadata)
            except Exception:
                resolved_metadata = {"raw_metadata": str(metadata)}
            # Ensure fundamental telemetry keys are guaranteed to be populated
            base_meta = generate_telemetry_metadata()
            for key, val in base_meta.items():
                resolved_metadata.setdefault(key, val)

        try:
            safe_message = str(message)
        except Exception:
            try:
                safe_message = repr(message)
            except Exception:
                safe_message = "<unstringable message>"

        return cls(
            passed=bool(passed),
            message=safe_message,
            metadata=resolved_metadata,
        )

    def to_dict(self) -> Dict[str, Any]:
        """Serializes the diagnostic result into a JSON-compatible dictionary."""
        try:
            meta_copy = dict(self.metadata)
        except Exception:
            meta_copy = {"raw_metadata": str(self.metadata)}

        return {
            "passed": self.passed,
            "message": self.message,
            "metadata": meta_copy,
        }

    def with_metadata(self, **additional_meta: Any) -> DiagnosticResult:
        """Creates a clone of the diagnostic result with extended metadata entries."""
        try:
            merged_meta = dict(self.metadata)
        except Exception:
            merged_meta = {}

        try:
            merged_meta.update(additional_meta)
        except Exception:
            for k, v in additional_meta.items():
                try:
                    merged_meta[str(k)] = v
                except Exception:
                    pass

        return DiagnosticResult(
            passed=self.passed,
            message=self.message,
            metadata=merged_meta,
        )


def validate_check_function(func: Union[Callable[..., Any], Any]) -> bool:
    """Validates that a check function is callable.

    Args:
        func: Object or callable to validate.

    Returns:
        bool: True if callable, False otherwise.
    """
    if func is None:
        return False
    try:
        return callable(func)
    except Exception:
        return False


def generate_telemetry_metadata(
    extra_context: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    """Generates standard telemetry metadata for diagnostic results.

    Args:
        extra_context: Optional mapping to merge into telemetry metadata.

    Returns:
        Dict[str, Any]: Telemetry dictionary containing timestamp, thread_id, and version.
    """
    now = time.time()
    try:
        thread_id: int = threading.get_ident()
    except Exception:
        thread_id = id(now)

    try:
        thread_name: str = threading.current_thread().name
    except Exception:
        thread_name = "unknown"

    try:
        iso_timestamp: str = datetime.datetime.fromtimestamp(
            now, tz=datetime.timezone.utc
        ).isoformat()
    except Exception:
        iso_timestamp = time.ctime(now)

    try:
        trace_id: str = uuid.uuid4().hex
    except Exception:
        trace_id = f"trace-{now}-{thread_id}"

    metadata: Dict[str, Any] = {
        "timestamp": now,
        "thread_id": thread_id,
        "version": _DEFAULT_VERSION,
        "iso_timestamp": iso_timestamp,
        "thread_name": thread_name,
        "trace_id": trace_id,
    }

    try:
        metadata["pid"] = os.getpid()
    except Exception:
        pass

    if extra_context:
        try:
            metadata.update(dict(extra_context))
        except Exception as err:
            metadata["_context_error"] = str(err)

    return metadata


def execute_diagnostic_safely(
    check_name: str,
    check_func: Callable[..., Any],
    *args: Any,
    **kwargs: Any,
) -> DiagnosticResult:
    """Safely executes a diagnostic callable with telemetry tracking and exception isolation.

    Args:
        check_name: Readable identifier for the diagnostic routine.
        check_func: Callable executing the validation logic.
        *args: Positional arguments forwarded to check_func.
        **kwargs: Keyword arguments forwarded to check_func.

    Returns:
        DiagnosticResult: Verified result object reflecting execution outcome.
    """
    safe_check_name = str(check_name) if check_name is not None else "unnamed_check"

    if not validate_check_function(check_func):
        return DiagnosticResult.create(
            passed=False,
            message=f"Check '{safe_check_name}' failed: supplied function is not callable.",
            metadata={"check_name": safe_check_name, "error_type": "InvalidCallable"},
        )

    start_time = time.monotonic()
    try:
        result = check_func(*args, **kwargs)
        duration_ms = (time.monotonic() - start_time) * 1000.0

        if isinstance(result, DiagnosticResult):
            extended = result.with_metadata(
                check_name=safe_check_name,
                duration_ms=duration_ms,
            )
            return extended
        elif isinstance(result, tuple) and len(result) >= 2:
            passed = bool(result[0])
            message = str(result[1])
            custom_meta: Dict[str, Any] = {}
            if len(result) > 2:
                raw_meta = result[2]
                if isinstance(raw_meta, (dict, Mapping)):
                    try:
                        custom_meta = dict(raw_meta)
                    except Exception:
                        custom_meta = {"raw_metadata": str(raw_meta)}
                else:
                    custom_meta = {"extra_return": str(raw_meta)}
            custom_meta.update({"check_name": safe_check_name, "duration_ms": duration_ms})
            return DiagnosticResult.create(passed=passed, message=message, metadata=custom_meta)
        elif isinstance(result, bool):
            return DiagnosticResult.create(
                passed=result,
                message=f"Check '{safe_check_name}' returned boolean {result}.",
                metadata={"check_name": safe_check_name, "duration_ms": duration_ms},
            )
        else:
            return DiagnosticResult.create(
                passed=True,
                message=f"Check '{safe_check_name}' executed successfully.",
                metadata={
                    "check_name": safe_check_name,
                    "duration_ms": duration_ms,
                    "return_type": type(result).__name__,
                },
            )
    except Exception as exc:
        duration_ms = (time.monotonic() - start_time) * 1000.0
        return DiagnosticResult.create(
            passed=False,
            message=f"Check '{safe_check_name}' encountered unhandled exception: {exc}",
            metadata={
                "check_name": safe_check_name,
                "duration_ms": duration_ms,
                "exception_type": type(exc).__name__,
                "exception_message": str(exc),
            },
        )

