    """Safely recursively transforms metadata values into serializable primitives.

    Prevents recursion loops and protects against unhandled serialization failures.
    """
    if depth > max_depth:
        return "<max_depth_exceeded>"
    if value is None or isinstance(value, (int, float, bool, str)):
        return value
    if isinstance(value, (datetime.datetime, datetime.date)):
        try:
            return value.isoformat()
        except Exception:
