def _normalize_timestamp(ts: float | int | None) -> float:
    """Safely normalizes and validates an epoch timestamp."""
    if ts is None:
        return time.time()
    try:
        val = float(ts)
        if math.isnan(val) or math.isinf(val) or val < 0:
            return time.time()
        return val
    except (ValueError, TypeError, OverflowError):
        return time.time()


def _safe_copy_mapping(data: Mapping[str, Any]) -> dict[str, Any]:
    """Safely deep-copies a mapping, falling back to shallow dictionary copy if un-copyable."""
    try:
        return copy.deepcopy(dict(data))
    except Exception:
        try:
            return dict(data)
        except Exception:
            return {}


def _validate_schema_id(schema_id: Any) -> str:
    """Defensively validates that schema_id is a non-empty string."""
    if not isinstance(schema_id, str):
        raise TypeError(f"Expected schema_id to be str, got {type(schema_id).__name__}")
    if not schema_id.strip():
        raise ValueError("schema_id cannot be empty or consist solely of whitespace")
    return schema_id


class ValidationResult(NamedTuple):
    """Represents the result of a schema validation operation."""

    is_valid: bool
    errors: list[str]
    timestamp: float

    @property
    def is_success(self) -> bool:
        """Indicates whether validation was successful without errors."""
        return self.is_valid and len(self.errors) == 0

    @classmethod
    def success(cls, timestamp: float | None = None) -> ValidationResult:
        """Create a successful validation outcome."""
        return cls(
            is_valid=True,
            errors=[],
            timestamp=_normalize_timestamp(timestamp),
        )

    @classmethod
    def failure(
        cls, errors: Sequence[str] | str, timestamp: float | None = None
    ) -> ValidationResult:
        """Create a failed validation outcome with normalized errors."""
        if isinstance(errors, str):
            err_list = [errors]
        elif isinstance(errors, (list, tuple, set)) or hasattr(errors, "__iter__"):
            err_list = [str(e) for e in errors]
        else:
            raise TypeError(f"Expected sequence of strings for errors, got {type(errors).__name__}")

        return cls(
            is_valid=False,
            errors=err_list,
            timestamp=_normalize_timestamp(timestamp),
        )

    @classmethod
    def from_dict(cls, data: Mapping[str, Any]) -> ValidationResult:
        """Construct a ValidationResult defensively from a dictionary."""
        if not isinstance(data, Mapping):
            raise TypeError(f"Expected mapping for ValidationResult data, got {type(data).__name__}")

        is_valid = bool(data.get("is_valid", False))
        raw_errors = data.get("errors", [])
        if raw_errors is None:
            errors: list[str] = []
        elif isinstance(raw_errors, (list, tuple, set)):
            errors = [str(e) for e in raw_errors]
        elif isinstance(raw_errors, str):
            errors = [raw_errors]
        elif hasattr(raw_errors, "__iter__"):
            errors = [str(e) for e in raw_errors]
        else:
            errors = [str(raw_errors)]

        timestamp = _normalize_timestamp(data.get("timestamp"))
        return cls(is_valid=is_valid, errors=errors, timestamp=timestamp)

    def to_dict(self) -> dict[str, Any]:
        """Serialize the validation result into a standard dictionary format."""
        return {
            "is_valid": bool(self.is_valid),
            "errors": list(self.errors),
            "timestamp": float(self.timestamp),
        }

    def has_errors(self) -> bool:
        """Determine if validation errors exist."""
        return len(self.errors) > 0


class SchemaDiagnosticReport(NamedTuple):
    """Encapsulates schema diagnostic evaluation results and metadata."""

    schema_id: str
    validation_result: ValidationResult
    telemetry: dict[str, Any]

