    ) -> SchemaDiagnosticReport:
        """Defensively construct a SchemaDiagnosticReport instance."""
        validated_schema_id = _validate_schema_id(schema_id)

        # Support duck-typing across divergent package namespaces and imports
        if isinstance(validation_result, ValidationResult):
            norm_result = validation_result
        elif hasattr(validation_result, "is_valid") and hasattr(validation_result, "errors"):
            raw_errs = validation_result.errors
            if raw_errs is None:
                err_list: list[str] = []
            elif isinstance(raw_errs, str):
                err_list = [raw_errs]
            elif isinstance(raw_errs, (list, tuple, set)) or hasattr(raw_errs, "__iter__"):
