            )
        elif isinstance(validation_result, Mapping):
            norm_result = ValidationResult.from_dict(validation_result)
        else:
            raise TypeError(
                f"Expected validation_result to be ValidationResult, got {type(validation_result).__name__}"
            )

        if telemetry is not None:
            if not isinstance(telemetry, Mapping):
                raise TypeError(
                    f"Expected telemetry to be a mapping or None, got {type(telemetry).__name__}"
                )
            telemetry_payload = _safe_copy_mapping(telemetry)
        else:
            telemetry_payload = generate_schema_telemetry(validated_schema_id)

        return cls(
            schema_id=validated_schema_id,
            validation_result=norm_result,
            telemetry=telemetry_payload,
        )

    def to_dict(self) -> dict[str, Any]:
        """Serialize the diagnostic report into a nested dictionary."""
        val_res_dict = (
            self.validation_result.to_dict()
            if hasattr(self.validation_result, "to_dict") and callable(self.validation_result.to_dict)
            else {
                "is_valid": bool(getattr(self.validation_result, "is_valid", False)),
                "errors": list(getattr(self.validation_result, "errors", [])),
                "timestamp": _normalize_timestamp(getattr(self.validation_result, "timestamp", None)),
            }
        )
        return {
            "schema_id": str(self.schema_id),
            "validation_result": val_res_dict,
            "telemetry": _safe_copy_mapping(self.telemetry) if isinstance(self.telemetry, Mapping) else dict(self.telemetry),
        }


def generate_schema_telemetry(
    schema_id: str, extra_metrics: dict[str, Any] | None = None
) -> dict[str, Any]:
    """Generates standard telemetry metadata for schema validation events.

    Args:
        schema_id: The unique identifier for the target schema.
        extra_metrics: Optional dictionary containing additional diagnostic attributes.

    Returns:
        A dictionary containing telemetry metadata attributes.

    Raises:
        TypeError: If schema_id is not a string or extra_metrics is not a dict.
        ValueError: If schema_id is empty or consist solely of whitespace.
    """
    validated_schema_id = _validate_schema_id(schema_id)

    telemetry: dict[str, Any] = {
        "schema_id": validated_schema_id,
        "timestamp": time.time(),
        "engine_version": ENGINE_VERSION,
        "node_id": id(schema_id),
    }

    if extra_metrics is not None:
        if not isinstance(extra_metrics, (dict, Mapping)):
            raise TypeError(
                f"Expected extra_metrics to be dict or None, got {type(extra_metrics).__name__}"
            )
        telemetry.update(_safe_copy_mapping(extra_metrics))

    return telemetry


def create_diagnostic_report(
    schema_id: str,
    is_valid: bool,
    errors: Sequence[str] | None = None,
    telemetry: dict[str, Any] | None = None,
) -> SchemaDiagnosticReport:
    """Convenience factory function for generating a complete diagnostic report."""
    _validate_schema_id(schema_id)
    if errors is None:
        err_list: list[str] = []
    elif isinstance(errors, str):
        err_list = [errors]
    elif isinstance(errors, (list, tuple, set)) or hasattr(errors, "__iter__"):
        err_list = [str(e) for e in errors]
    else:
        raise TypeError(f"Expected sequence of strings for errors, got {type(errors).__name__}")

    result = (
        ValidationResult.success()
        if is_valid and not err_list
        else ValidationResult.failure(err_list)
    )
    return SchemaDiagnosticReport.create(
        schema_id=schema_id, validation_result=result, telemetry=telemetry
    )


