                    metrics_data = {"error": "metrics_to_dict_failed", "raw": str(self.health_metrics)}
            elif hasattr(self.health_metrics, "_asdict") and callable(self.health_metrics._asdict):
                try:
                    metrics_data = self.health_metrics._asdict()
                except Exception:
                    metrics_data = {"error": "metrics_asdict_failed", "raw": str(self.health_metrics)}
            else:
                metrics_data = {"raw": str(self.health_metrics)}

        snapshot_data: Optional[Dict[str, Any]] = None
        if self.state_snapshot is not None:
            if hasattr(self.state_snapshot, "to_dict") and callable(self.state_snapshot.to_dict):
                try:
                    snapshot_data = self.state_snapshot.to_dict()
                except Exception:
                    snapshot_data = {"error": "snapshot_to_dict_failed", "raw": str(self.state_snapshot)}
