            else:
                snapshot_data = {"raw": str(self.state_snapshot)}

        return {
            "status": self.status.value if isinstance(self.status, RegistryStatus) else str(self.status),
            "timestamp": self.timestamp,
            "checks": checks_dict,
            "summary": dict(self.summary) if isinstance(self.summary, dict) else {},
            "telemetry": dict(self.telemetry) if isinstance(self.telemetry, dict) else {},
            "health_metrics": metrics_data,
            "state_snapshot": snapshot_data,
        }


class KnowledgeEntry(NamedTuple):
    """Schema for individual knowledge base entries."""

    id: str
    category: str
    content: Any
    version: int
    tags: List[str]
    last_updated: str

    def to_dict(self) -> Dict[str, Any]:
        """Convert entry to a JSON-compatible dictionary."""
        tags_list = list(self.tags) if isinstance(self.tags, (list, tuple, set)) else [str(self.tags)]
        return {
            "id": self.id,
            "category": self.category,
            "content": self.content,
            "version": self.version,
            "tags": tags_list,
            "last_updated": self.last_updated,
        }


class RegistryEvent(NamedTuple):
    """Audit log structure for registry state changes."""

    event_type: str
    timestamp: float
    actor: str
    details: Dict[str, Any]

    def to_dict(self) -> Dict[str, Any]:
        """Convert event to a JSON-compatible dictionary."""
        return {
            "event_type": self.event_type,
            "timestamp": self.timestamp,
            "actor": self.actor,
            "details": dict(self.details) if isinstance(self.details, dict) else {},
        }


class DiagnosticAware(NamedTuple):
    """Protocol for objects that can self-report their health status."""

    check_fn: Callable[[], RegistryDiagnosticResult]
    priority: int
    last_run: float


def create_telemetry(
    latency: float,
    memory: int,
    context: Optional[DiagnosticContext] = None,
) -> RegistryTelemetry:
    """Factory function for generating standard telemetry with diagnostic context.

    Args:
        latency: Operation latency in milliseconds.
        memory: Memory usage in kilobytes.
        context: Optional diagnostic context metadata.

    Returns:
        RegistryTelemetry instance populated with current timestamp and thread info.

    Raises:
        ValueError: If latency or memory parameters are invalid negative numbers.
    """
    if (
        not isinstance(latency, (int, float))
        or math.isnan(latency)
        or math.isinf(latency)
        or latency < 0
    ):
        raise ValueError(f"Latency must be a non-negative finite float, got {latency!r}")
    if isinstance(memory, bool) or not isinstance(memory, int) or memory < 0:
        raise ValueError(f"Memory usage must be a non-negative integer, got {memory!r}")

    return RegistryTelemetry(
        timestamp=time.time(),
        thread_id=threading.get_ident(),
        version=TELEMETRY_VERSION,
        operation_latency_ms=float(latency),
        memory_usage_kb=memory,
        context=context,
    )


def create_diagnostic_result(
    passed: bool,
    message: str,
    metadata: Optional[Dict[str, Any]] = None,
    telemetry: Optional[RegistryTelemetry] = None,
) -> RegistryDiagnosticResult:
    """Defensive helper factory for generating diagnostic results."""
    return RegistryDiagnosticResult(
        passed=bool(passed),
        message=str(message),
        metadata=dict(metadata) if metadata is not None else {},
        telemetry=telemetry,
    )


def create_diagnostic_report(
    status: Union[RegistryStatus, str],
    checks: Optional[Dict[str, RegistryDiagnosticResult]] = None,
    summary: Optional[Dict[str, Any]] = None,
    telemetry: Optional[Dict[str, Any]] = None,
    health_metrics: Optional[RegistryHealthMetrics] = None,
    state_snapshot: Optional[RegistryStateSnapshot] = None,
    timestamp: Optional[str] = None,
) -> RegistryDiagnosticReport:
    """Defensive helper factory for generating comprehensive RegistryDiagnosticReport instances."""
    resolved_status = (
        status if isinstance(status, RegistryStatus)
        else RegistryStatus.from_str(str(status))
    )
    ts = timestamp if isinstance(timestamp, str) and timestamp.strip() else time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
    return RegistryDiagnosticReport(
        status=resolved_status,
        timestamp=ts,
        checks=dict(checks) if checks is not None else {},
        summary=dict(summary) if summary is not None else {},
        telemetry=dict(telemetry) if telemetry is not None else {},
        health_metrics=health_metrics,
        state_snapshot=state_snapshot,
    )


def create_knowledge_entry(
    id_: str,
    category: str,
    content: Any,
    version: int = 1,
    tags: Optional[List[str]] = None,
    last_updated: Optional[str] = None,
) -> KnowledgeEntry:
    """Defensive helper factory for creating validated KnowledgeEntry structures."""
    if not isinstance(id_, str) or not id_.strip():
        raise ValueError(f"Knowledge entry ID must be a non-empty string, got {id_!r}")
    if not isinstance(category, str) or not category.strip():
        raise ValueError(f"Knowledge entry category must be a non-empty string, got {category!r}")
    if isinstance(version, bool) or not isinstance(version, int) or version < 0:
        raise ValueError(f"Knowledge entry version must be a non-negative integer, got {version!r}")

    clean_tags: List[str] = [str(t).strip() for t in (tags or []) if str(t).strip()]
    ts = last_updated if isinstance(last_updated, str) and last_updated.strip() else time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())

    return KnowledgeEntry(
        id=id_.strip(),
        category=category.strip(),
        content=content,
        version=version,
        tags=clean_tags,
        last_updated=ts,
    )


def create_event(
    event_type: str,
    actor: str = "system",
    details: Optional[Dict[str, Any]] = None,
    timestamp: Optional[float] = None,
) -> RegistryEvent:
    """Defensive helper factory for generating RegistryEvent audit logs."""
    sanitized_type = str(event_type).strip() if event_type is not None else ""
    if not sanitized_type:
        sanitized_type = "UNKNOWN_EVENT"

    sanitized_actor = str(actor).strip() if actor is not None else ""
    if not sanitized_actor:
        sanitized_actor = "system"

    ts: float
    if timestamp is not None and isinstance(timestamp, (int, float)) and not math.isnan(timestamp) and not math.isinf(timestamp) and timestamp >= 0:
        ts = float(timestamp)
    else:
        ts = time.time()

    return RegistryEvent(
        event_type=sanitized_type,
        timestamp=ts,
        actor=sanitized_actor,
        details=dict(details) if details is not None else {},
    )

