@final
class RegistrySchemaValidator:
    """Provides static validation logic and serialization helpers for registry types."""

    __slots__ = ()

    @staticmethod
    def _is_safe_collection(val: Any) -> bool:
        """Internal helper to ensure collection is valid iterable and not a string/bytes."""
        return isinstance(val, (list, tuple, set, frozenset))

    @staticmethod
    def validate_entry(entry: KnowledgeEntry) -> bool:
        """Validates that a KnowledgeEntry conforms to required schema constraints.

        Args:
            entry (KnowledgeEntry): The knowledge entry instance to validate.

        Returns:
            bool: True if the entry passes all validation constraints, False otherwise.
        """
        if entry is None:
            return False

        try:
            entry_id = getattr(entry, "id", None)
            if not isinstance(entry_id, str) or not entry_id.strip():
                return False

            version = getattr(entry, "version", None)
            # Ensure version is specifically an int (excluding bool subclasses) and non-negative
            if type(version) is not int or version < 0:
                return False

            title = getattr(entry, "title", None)
            if title is not None and not isinstance(title, str):
                return False

            domain = getattr(entry, "domain", None)
            if domain is not None and not isinstance(domain, str):
                return False

            tags = getattr(entry, "tags", None)
            if tags is not None:
                if not isinstance(tags, (list, tuple, set, frozenset)):
                    return False
                # Verify elements within tags are strings if provided
                for t in tags:
                    if not isinstance(t, str):
                        return False

            metadata = getattr(entry, "metadata", None)
            if metadata is not None and not isinstance(metadata, dict):
                return False

            dependencies = getattr(entry, "dependencies", None)
            if dependencies is not None:
                if not isinstance(dependencies, (list, tuple, set, frozenset)):
                    return False
                for dep in dependencies:
                    if not isinstance(dep, str):
                        return False

            return True
        except (AttributeError, TypeError, Exception) as err:
            logger.debug("Schema validation exception encountered: %s", err)
            return False

    @staticmethod
    def validate_entry_diagnostics(entry: KnowledgeEntry) -> ValidationResult:
        """Performs comprehensive validation of a KnowledgeEntry with telemetry reporting.

        Args:
            entry (KnowledgeEntry): The knowledge entry instance to inspect.

        Returns:
            ValidationResult: Detailed validation outcome including error logs and timestamp.
        """
        now = time.time()
        errors: List[str] = []

        if entry is None:
            return ValidationResult(
                is_valid=False,
                errors=["KnowledgeEntry cannot be None."],
                timestamp=now,
            )

        try:
            entry_id = getattr(entry, "id", None)
            if entry_id is None:
                errors.append("Invalid or missing 'id': must be a non-empty string.")
            elif not isinstance(entry_id, str):
                errors.append(f"Invalid 'id': expected str, got {type(entry_id).__name__}.")
            elif not entry_id.strip():
                errors.append("Invalid 'id': string cannot be empty or whitespace only.")

            version = getattr(entry, "version", None)
            if version is None:
                errors.append("Invalid or missing 'version': must be a non-negative integer.")
            elif type(version) is not int:
                errors.append(f"Invalid 'version': expected int, got {type(version).__name__}.")
            elif version < 0:
                errors.append(f"Invalid 'version': cannot be negative (got {version}).")

            title = getattr(entry, "title", None)
            if title is not None and not isinstance(title, str):
                errors.append(f"Invalid 'title': must be a string if provided (got {type(title).__name__}).")

            domain = getattr(entry, "domain", None)
            if domain is not None and not isinstance(domain, str):
                errors.append(f"Invalid 'domain': must be a string if provided (got {type(domain).__name__}).")

            tags = getattr(entry, "tags", None)
            if tags is not None:
                if not isinstance(tags, (list, tuple, set, frozenset)):
                    errors.append(f"Invalid 'tags': must be a collection if provided (got {type(tags).__name__}).")
                else:
                    invalid_tags = [t for t in tags if not isinstance(t, str)]
                    if invalid_tags:
                        errors.append(f"Invalid elements in 'tags': all items must be strings (found {len(invalid_tags)} non-string elements).")

            metadata = getattr(entry, "metadata", None)
            if metadata is not None and not isinstance(metadata, dict):
                errors.append(f"Invalid 'metadata': must be a dictionary if provided (got {type(metadata).__name__}).")

            dependencies = getattr(entry, "dependencies", None)
            if dependencies is not None:
                if not isinstance(dependencies, (list, tuple, set, frozenset)):
                    errors.append(f"Invalid 'dependencies': must be a collection if provided (got {type(dependencies).__name__}).")
                else:
                    invalid_deps = [d for d in dependencies if not isinstance(d, str)]
                    if invalid_deps:
                        errors.append(f"Invalid elements in 'dependencies': all items must be strings (found {len(invalid_deps)} non-string elements).")

        except Exception as err:
            logger.debug("Unexpected error during diagnostic validation: %s", err)
            errors.append(f"Validation introspection error: {err}")

        return ValidationResult(
            is_valid=len(errors) == 0,
            errors=errors,
            timestamp=now,
        )

    @staticmethod
    def generate_diagnostic_report(entry: KnowledgeEntry) -> SchemaDiagnosticReport:
        """Generates an enterprise-grade schema diagnostic report for an entry.

        Args:
            entry (KnowledgeEntry): The target entry to assess.

        Returns:
            SchemaDiagnosticReport: Populated diagnostic report structure.
        """
        res = RegistrySchemaValidator.validate_entry_diagnostics(entry)
        target_id: Optional[str] = None
        warnings: List[str] = []

        if entry is not None:
            raw_id = getattr(entry, "id", None)
            if raw_id is not None:
                target_id = str(raw_id).strip() or None

            # Detect non-critical warnings
            content = getattr(entry, "content", None)
            if content is None or (isinstance(content, str) and not content.strip()):
                warnings.append("Entry content is empty.")

            tags = getattr(entry, "tags", None)
            if tags is not None and len(tags) == 0:
                warnings.append("Tags list is present but empty.")

        report = SchemaDiagnosticReport(
            target_id=target_id,
            is_valid=res.is_valid,
            errors=res.errors,
            warnings=warnings,
            metrics={"checked_timestamp": res.timestamp, "error_count": len(res.errors), "warning_count": len(warnings)},
        )
        return report

    @staticmethod
    def to_dict(entry: KnowledgeEntry) -> Dict[str, Any]:
        """Serializes a KnowledgeEntry to a dictionary for storage/telemetry.

        Args:
            entry (KnowledgeEntry): The knowledge entry to serialize.

        Returns:
            Dict[str, Any]: Dictionary representation of the knowledge entry.

        Raises:
            TypeError: If the entry cannot be serialized to a dictionary.
        """
        if entry is None:
            raise TypeError("Object of type 'NoneType' cannot be serialized to dict.")

        if isinstance(entry, dict):
            return dict(entry)

        if dataclasses.is_dataclass(entry) and not isinstance(entry, type):
            try:
                return dataclasses.asdict(entry)
            except Exception as err:
                logger.debug("Failed calling dataclasses.asdict on entry: %s", err)

        if hasattr(entry, "to_dict") and callable(entry.to_dict):
            try:
                res = entry.to_dict()
                if isinstance(res, dict):
                    return dict(res)
            except Exception as err:
                logger.debug("Failed calling to_dict on entry: %s", err)

        if hasattr(entry, "_asdict") and callable(entry._asdict):
            try:
                return dict(entry._asdict())
            except Exception as err:
                logger.debug("Failed calling _asdict on entry: %s", err)

        if hasattr(entry, "__dict__"):
            try:
                result = dict(entry.__dict__)
                # Filter out private mangled attributes if any
                return {k: v for k, v in result.items() if not k.startswith("_")}
            except Exception as err:
                logger.debug("Failed copying __dict__ on entry: %s", err)

        # Fallback inspection for slot-based objects
        if hasattr(entry, "__slots__"):
            try:
                slots = getattr(entry, "__slots__")
                if isinstance(slots, str):
                    slots = [slots]
                res: Dict[str, Any] = {}
                for slot in slots:
                    if hasattr(entry, slot):
                        res[slot] = getattr(entry, slot)
                if res:
                    return res
            except Exception as err:
                logger.debug("Failed extracting slots from entry: %s", err)

        raise TypeError(f"Object of type '{type(entry).__name__}' cannot be serialized to dict.")

