                        empty_tags = [t for t in tags if isinstance(t, str) and not t.strip()]
                        if empty_tags:
                            warnings.append(f"Tags collection contains {len(empty_tags)} empty or whitespace-only strings.")
                        # Check for duplicates in sequence collections
                        if isinstance(tags, (list, tuple)):
                            unique_tags = set(tags)
                            if len(unique_tags) < len(tags):
                                warnings.append(f"Tags collection contains duplicate elements ({len(tags) - len(unique_tags)} duplicates).")

            metadata = getattr(entry, "metadata", None)
            if isinstance(metadata, dict):
                non_str_keys = [k for k in metadata.keys() if not isinstance(k, str)]
                if non_str_keys:
                    warnings.append(f"Metadata contains {len(non_str_keys)} non-string keys.")

        elapsed_ms = (time.perf_counter() - start_time) * 1000.0

        report = SchemaDiagnosticReport(
            target_id=target_id,
            is_valid=res.is_valid,
            errors=res.errors,
            warnings=warnings,
            metrics={
                "checked_timestamp": res.timestamp,
                "error_count": len(res.errors),
                "warning_count": len(warnings),
                "evaluation_ms": round(elapsed_ms, 4),
            },
        )
        return report

    @staticmethod
    def to_dict(entry: KnowledgeEntry) -> Dict[str, Any]:
        """Serializes a KnowledgeEntry to a dictionary for storage/telemetry.

        Args:
            entry (KnowledgeEntry): The knowledge entry to serialize.

        Returns:
            Dict[str, Any]: Dictionary representation of the knowledge entry.

        Raises:
            TypeError: If the entry cannot be serialized to a dictionary.
        """
        if entry is None:
            raise TypeError("Object of type 'NoneType' cannot be serialized to dict.")

        if isinstance(entry, dict):
            return copy.copy(entry)

        if dataclasses.is_dataclass(entry) and not isinstance(entry, type):
            try:
                return dataclasses.asdict(entry)
            except Exception as err:
