    io_wait_ms: float = 0.0,
) -> RegistryHealthMetrics:
    """Defensive factory for generating bounded RegistryHealthMetrics."""
    safe_cpu = _safe_float(cpu_load, default=0.0, min_val=0.0)
    safe_threads = _safe_int(active_threads, default=0, min_val=0)
    safe_hit_rate = _safe_float(cache_hit_rate, default=1.0, min_val=0.0, max_val=1.0)
    safe_io_wait = _safe_float(io_wait_ms, default=0.0, min_val=0.0)

    return RegistryHealthMetrics(
        cpu_load=safe_cpu,
        active_threads=safe_threads,
        cache_hit_rate=safe_hit_rate,
        io_wait_ms=safe_io_wait,
    )


def summarize_diagnostic_results(checks: Dict[str, RegistryDiagnosticResult]) -> Dict[str, Any]:
    """Generates a summary dictionary of check counts and execution statistics."""
    try:
        safe_checks = dict(checks) if isinstance(checks, (dict, Mapping)) else {}
    except Exception:
        safe_checks = {}
    total = len(safe_checks)
    passed = 0
    total_duration = 0.0
    for c in safe_checks.values():
        if c is not None and getattr(c, "passed", False) is True:
            passed += 1
        dur = _safe_float(getattr(c, "duration_ms", 0.0), default=0.0, min_val=0.0)
        total_duration += dur
    failed = max(0, total - passed)

    return {
        "total_checks": total,
        "passed_checks": passed,
        "failed_checks": failed,
        "health_score": compute_health_score(safe_checks),
        "total_duration_ms": round(total_duration, 4),
    }


def format_diagnostic_report(
    status: str,
    checks: Dict[str, RegistryDiagnosticResult],
) -> RegistryDiagnosticReport:
    """Constructs a finalized diagnostic report object and logs the completion event with fault-tolerant logging wrapper."""
    try:
        safe_checks = dict(checks) if isinstance(checks, (dict, Mapping)) else {}
    except Exception:
        safe_checks = {}
    safe_status = str(status).strip() if status is not None else "UNKNOWN"
    if not safe_status:
        safe_status = "UNKNOWN"
    score = compute_health_score(safe_checks)
    telemetry = generate_registry_telemetry()

    try:
        rep_id = str(uuid.uuid4())
    except Exception:
        rep_id = f"rep-{int(time.time() * 1000)}"

    curr_time = _safe_float(time.time(), default=0.0, min_val=0.0)

    report = RegistryDiagnosticReport(
        report_id=rep_id,
        timestamp=curr_time,
        status=safe_status,
        checks=safe_checks,
        health_score=score,
        telemetry=telemetry,
    )

    try:
        try:
            logger = DiagnosticLogger()
        except Exception:
            logger = None

        if logger is not None:
            log_fn = getattr(logger, "log_event", None)
            if callable(log_fn):
                log_fn(
                    "REPORT_GENERATED",
                    {
                        "report_id": report.report_id,
                        "status": report.status,
                        "health_score": report.health_score,
                    },
                )
    except Exception:
        # Non-critical telemetry logging errors are caught to preserve report emission
        pass

    return report


